export const newVault = (now: number, seed = 0): VaultHome => ({ seed, layout: 3, rooms: [{ type: 'entry', level: 0, ...ENTRY_AT, furniture: [] }], settlers: [], from: 50, sessionAt: now, seenAt: now, boost: 0, boostAt: now });

// ---- the grid ----

export const slotsOf = (r: VaultRoom): number => roomDef(r.type).slots;
/** Stairwells and hallways are passages: they take no slot, add no happiness and make no settlers. */
export const isPassage = (r: { type: RoomType }): boolean => r.type === 'stairs' || r.type === 'hallway';
export const slotsUsed = (v: VaultHome): number => v.rooms.reduce((n, r) => n + (isPassage(r) ? 0 : slotsOf(r)), 0);
/** How many rooms there are, not counting the entryway, the hallways or the stairwells. */
export const roomCount = (v: VaultHome): number => v.rooms.filter((r) => !isPassage(r) && r.type !== 'entry').length;
export const furnitureCount = (v: VaultHome): number => v.rooms.reduce((n, r) => n + (isPassage(r) ? 0 : r.furniture.length), 0);
export const hallwaysOn = (v: VaultHome, level: number): number => v.rooms.filter((r) => r.type === 'hallway' && r.level === level).length;
export const roomsOn = (v: VaultHome, level: number): VaultRoom[] => v.rooms.filter((r) => r.level === level);
/** The deepest level that has a room. */
export const deepestLevel = (v: VaultHome): number => v.rooms.reduce((m, r) => Math.max(m, r.level), 0);

/** The room covering a cell of a level, or undefined. */
export const roomAt = (v: VaultHome, level: number, col: number, row: number): VaultRoom | undefined => v.rooms.find((r) => r.level === level && r.row === row && col >= r.col && col < r.col + slotsOf(r));

/** What the vault says if you try to build before the entryway's decontamination shower is in. It is never written on the furniture itself. */
export const DECON_REASON = 'The vault will not let you build until everyone coming in has been decontaminated';
export const hasDecon = (v: VaultHome): boolean => v.legacy === true || v.rooms.some((r) => r.type === 'entry' && r.furniture.includes('decon'));

/** The cell on the entryway's front-left side stays empty for good: that wall holds the vault door. */
export const isDoorCell = (v: VaultHome, level: number, col: number, row: number): boolean =>
  v.rooms.some((r) => r.type === 'entry' && r.level === level && col === r.col && row === r.row + 1);

// ---- stairwells ----
// A stairwell is built like any room, and goes up or down: it makes a second one in the same place on the level above or below, which is where the owner arrives
// (it costs nothing). A level has at most two stairwells (either end of one counts). The arrows between levels only show where there is a stairwell to use, and every
// room has to stay joined to the entryway, next door on its own level or up and down a stairwell.

/** How many stairwells a level can hold, counting both ends. */
export const STAIRS_PER_LEVEL = 2;
export type StairDir = 'up' | 'down';
/** The stairwell that was made for you by building the one at the other end. */
export const isTwin = (r: VaultRoom): boolean => r.type === 'stairs' && r.twin === true;
/** Is there a stairwell between this level and the one below it? (An old vault dug a stairwell under a room: that counts too.) */
export const hasWayDown = (v: VaultHome, level: number): boolean => v.rooms.some((r) => r.type === 'stairs' && ((r.level === level && roomAt(v, level + 1, r.col, r.row)?.type === 'stairs') || (r.level === level + 1 && !!roomAt(v, level, r.col, r.row))));
export const hasWayUp = (v: VaultHome, level: number): boolean => level > 0 && hasWayDown(v, level - 1);
/** How many stairwells have been built (not counting the twin each one makes). */
export const stairwellsBuilt = (v: VaultHome): number => v.rooms.filter((r) => r.type === 'stairs' && !isTwin(r)).length;
/** Which way a stairwell goes: down if there is a stairwell under it, up if there is one over it (an old one, dug under a room, goes up). */
export const stairDir = (v: VaultHome, r: VaultRoom): StairDir | null => {
  if (r.type !== 'stairs') return null;
  if (roomAt(v, r.level + 1, r.col, r.row)?.type === 'stairs') return 'down';
  return r.level > 0 && roomAt(v, r.level - 1, r.col, r.row) ? 'up' : null;
};

/** The rooms around a cell of a level, with the side of the cell each is on. */
const around = (v: VaultHome, level: number, col: number, row: number): { face: Face; room: VaultRoom }[] =>
  (Object.keys(FACE_STEP) as Face[]).flatMap((face) => { const room = roomAt(v, level, col + FACE_STEP[face][0], row + FACE_STEP[face][1]); return room ? [{ face, room }] : []; });
/** Which side the open end of a stairwell built here would be on: the side of the one room it is joined to. Null if it is not joined to exactly one room. */
export function stairFace(v: VaultHome, level: number, col: number, row: number): Face | null {
  const near = around(v, level, col, row);
  return near.length === 1 ? near[0].face : null;
}

export type StairShape = 'straight' | 'u';

/** What every stairwell needs, whatever its shape: a level to go to, and room for another stairwell on both levels. */
function whyNotLevels(v: VaultHome, level: number, dir: StairDir): string | null {
  const other = dir === 'down' ? level + 1 : level - 1;
  if (other >= LEVELS) return 'There is nothing below the fifth level';
  if (other < 0) return 'There is nothing above the first level';
  if (roomsOn(v, level).filter((r) => r.type === 'stairs').length >= STAIRS_PER_LEVEL) return `A level holds at most ${STAIRS_PER_LEVEL} stairwells`;
  if (roomsOn(v, other).filter((r) => r.type === 'stairs').length >= STAIRS_PER_LEVEL) return `The level ${dir === 'down' ? 'below' : 'above'} already has ${STAIRS_PER_LEVEL} stairwells`;
  return null;
}

/** Can a straight stairwell going this way be built at this cell of this level? Null if yes, or the reason. */
export function whyNotStairs(v: VaultHome, level: number, col: number, row: number, dir: StairDir): string | null {
  const other = dir === 'down' ? level + 1 : level - 1;
  const limits = whyNotLevels(v, level, dir);
  if (limits) return limits;
  // a stairwell is a dead-end corridor: it joins the one room it is built onto, and nothing else can touch it
  const near = around(v, level, col, row);
  if (near.length === 0) return 'A stairwell has to be built onto a room or a hallway';
  if (near.length > 1) return 'A stairwell is a dead end: it can only touch the one room it is built onto';
  if (near[0].room.type === 'stairs') return 'A stairwell cannot be built onto another stairwell';
  // with every room slot used there is nothing to put on a level that has not been reached yet (the entryway, hallways and stairwells take no slot)
  if (roomsOn(v, other).length === 0 && settlerSlots(v) >= MAX_SLOTS) return 'Every room slot is used: you cannot go down to a new level';
  // the other end opens the opposite way, onto the cell on the far side: at the very edge of the vault there is none, and a straight flight would end in the edge with no room to turn
  const away = FACE_STEP[OPPOSITE[near[0].face]];
  const beyond = [col + away[0], row + away[1]];
  if (beyond[0] < 0 || beyond[0] >= COLS || beyond[1] < 0 || beyond[1] >= ROWS) return 'At the very edge of the vault a straight stairwell would run into the edge on the other level: it has to be a U-shaped one, which turns back';
  if (roomAt(v, other, col, row)) return `There is already a room ${dir === 'down' ? 'under' : 'over'} it`;
  if (isDoorCell(v, other, col, row)) return 'That is the wall with the vault door on the level above: it stays clear';
  // at the other end the corridor picks up from the opposite side: nothing may be beside it on the other three
  const open = OPPOSITE[near[0].face];
  const beside = around(v, other, col, row).filter((n) => n.face !== open);
  if (beside.length > 0) return `There is something in the way beside it on the level ${dir === 'down' ? 'below' : 'above'}`;
  return null;
}

// A U-shaped stairwell takes one cell, like a straight one, and can be built onto any side of a room (it is only DRAWN about as big as a bathroom, with two hallway-wide
// flights side by side). You walk in at its open end, on the side of the room it is built onto, climb the first flight away from the room to a landing at the far end, turn,
// and the second flight brings you back toward the room, out beside where you came in, on the next level. So at the edge of the vault it turns back instead of running into
// the edge. The twin on the other level is in the same cell and opens the same way (a straight one opens the opposite way), arriving on the other lane.

export type UPlan = { col: number; row: number; entry: 0 | 1; face: Face };

/** The plan for a U stairwell built at this cell going this way: it opens toward the one room the cell touches. Or the reason it cannot be built. */
export function uStairPlan(v: VaultHome, level: number, col: number, row: number, dir: StairDir): UPlan | string {
  const limits = whyNotLevels(v, level, dir);
  if (limits) return limits;
  const other = dir === 'down' ? level + 1 : level - 1;
  const way = dir === 'down' ? 'below' : 'above';
  // a stairwell is a dead-end corridor: it joins the one room it is built onto, and nothing else can touch it
  const near = around(v, level, col, row);
  if (near.length === 0) return 'A stairwell has to be built onto a room or a hallway';
  if (near.length > 1) return 'A stairwell is a dead end: it can only touch the one room it is built onto';
  if (near[0].room.type === 'stairs') return 'A stairwell cannot be built onto another stairwell';
  if (roomsOn(v, other).length === 0 && settlerSlots(v) >= MAX_SLOTS) return 'Every room slot is used: you cannot go down to a new level';
  if (roomAt(v, other, col, row)) return `There is already a room ${dir === 'down' ? 'under' : 'over'} it`;
  if (isDoorCell(v, other, col, row)) return 'That is the wall with the vault door on the level above: it stays clear';
  // at the other end it opens the same way: nothing may be beside it on the other three sides
  const face = near[0].face;
  const beside = around(v, other, col, row).filter((nb) => nb.face !== face);
  if (beside.length > 0) return `There is something in the way beside it on the level ${way}`;
  return { col, row, entry: 0, face };
}

/** Can a stairwell of this shape (none chosen yet: either) going this way be built at this cell? Null if yes, or the reason. */
export function whyNotStairShape(v: VaultHome, level: number, col: number, row: number, dir: StairDir, shape?: StairShape): string | null {
  const straight = shape === 'u' ? null : whyNotStairs(v, level, col, row, dir);
  if (shape !== 'u' && !straight) return null;
  if (shape === 'straight') return straight;
  const u = uStairPlan(v, level, col, row, dir);
  if (typeof u !== 'string') return null;
  return shape === 'u' ? u : straight;
}

// ---- keeping everything joined ----

const coversCell = (r: VaultRoom, col: number, row: number): boolean => r.row === row && col >= r.col && col < r.col + slotsOf(r);
/** A stairwell joins another room only at its open end: is this room (not a stairwell, or one that opens here) allowed to join it? */
const opensTo = (stairs: VaultRoom, other: VaultRoom): boolean => {
  const oc = openCell(stairs);
  return !oc || coversCell(other, oc[0], oc[1]);
};
/** Do two rooms of the same level share a wall? (Not at a corner.) */
const nextTo = (a: VaultRoom, b: VaultRoom): boolean =>
  a.level === b.level && opensTo(a, b) && opensTo(b, a) && (Array.from({ length: slotsOf(a) }, (_, k) => a.col + k).some((c) => coversCell(b, c - 1, a.row) || coversCell(b, c + 1, a.row) || coversCell(b, c, a.row - 1) || coversCell(b, c, a.row + 1))
    || Array.from({ length: slotsOf(b) }, (_, k) => b.col + k).some((c) => coversCell(a, c - 1, b.row) || coversCell(a, c + 1, b.row) || coversCell(a, c, b.row - 1) || coversCell(a, c, b.row + 1)));
/** Does a stairwell join these two rooms (one is a stairwell and the other is in the same place on the level above or below it)? */
const joinedByStairs = (a: VaultRoom, b: VaultRoom): boolean =>
  Math.abs(a.level - b.level) === 1 && ((a.type === 'stairs' && coversCell(b, a.col, a.row)) || (b.type === 'stairs' && coversCell(a, b.col, b.row)));
/** Every room that can be reached from the entryway without the ones skipped: through a shared wall on its level, or up and down a stairwell. */
export function reachable(v: VaultHome, skip: VaultRoom[] = []): Set<VaultRoom> {
  const rooms = v.rooms.filter((r) => !skip.includes(r));
  const start = rooms.find((r) => r.type === 'entry') ?? rooms[0];
  const seen = new Set<VaultRoom>();
  if (!start) return seen;
  seen.add(start);
  const queue = [start];
  while (queue.length) {
    const r = queue.shift() as VaultRoom;
    for (const o of rooms) if (!seen.has(o) && (nextTo(r, o) || joinedByStairs(r, o))) { seen.add(o); queue.push(o); }
  }
  return seen;
}

/** Can a room of this type be built with its left cell here? Returns null if yes, or the reason. */
export function whyNotBuild(v: VaultHome, type: RoomType, level: number, col: number, row: number, dir?: StairDir, shape?: StairShape): string | null {
  const def = roomDef(type);
  if (def.buildable === false) return 'There is only one entryway';
  if (!hasDecon(v)) return DECON_REASON;
  if (level < 0 || level >= LEVELS || row < 0 || row >= ROWS || col < 0 || col + def.slots > COLS) return 'There is no room for it there';
  if (type === 'stairs') {
    // no way chosen yet (the list of rooms): it can be built if it can go either way
    const down = dir === 'up' ? null : whyNotStairShape(v, level, col, row, 'down', shape);
    const up = dir === 'down' ? null : whyNotStairShape(v, level, col, row, 'up', shape);
    if (dir === 'down' && down) return down;
    if (dir === 'up' && up) return up;
    if (dir === undefined && down && up) return level + 1 < LEVELS ? down : up;
  }
  if (type !== 'hallway' && type !== 'stairs' && settlerSlots(v) + def.slots > MAX_SLOTS) return 'Room limit reached';
  if (type === 'hallway' && hallwaysOn(v, level) >= MAX_HALLWAYS_PER_LEVEL) return `A level holds at most ${MAX_HALLWAYS_PER_LEVEL} hallways`;
  if (type !== 'hallway' && type !== 'stairs' && v.rooms.filter((r) => r.type === type).length >= def.max) return `A vault holds at most ${def.max} ${def.name}${def.max > 1 ? 's' : ''}`;
  for (let c = col; c < col + def.slots; c++) if (roomAt(v, level, c, row)) return 'That space is taken';
  for (let c = col; c < col + def.slots; c++) if (isDoorCell(v, level, c, row)) return 'That wall is the vault door: it stays clear';
  if (roomsOn(v, level).length === 0 && type !== 'stairs') return 'There is nothing here to build on';
  // a stairwell is a dead end: nothing joins its sides or its far end, only the open end
  for (let c = col; c < col + def.slots; c++) {
    for (const [dc, dr] of [[-1, 0], [1, 0], [0, -1], [0, 1]]) {
      const o = roomAt(v, level, c + dc, row + dr);
      if (o && o.type === 'stairs' && o.face && type !== 'stairs') { const oc = openCell(o) as [number, number]; if (!(oc[0] === c && oc[1] === row)) return 'A stairwell is a dead end: only its open end joins a room'; }
    }
  }
  // after that, it must touch a room of the same level, not at a corner
  let touches = false;
  for (let c = col; c < col + def.slots; c++) {
    for (const [dc, dr] of [[-1, 0], [1, 0], [0, -1], [0, 1]]) {
      const o = roomAt(v, level, c + dc, row + dr);
      if (o && !(o.row === row && c + dc >= col && c + dc < col + def.slots)) touches = true;
    }
  }
  return touches ? null : 'It has to connect to a room you already have';
}

/**
 * Brings a vault saved in the old layout (three rooms across, five down, side view) into the floorplan: each old row becomes a level, the rooms keep their
 * furniture, and an entryway is added next to the first room. Such a vault is marked legacy: it keeps what it has and the new rules (decontamination,
 * three rooms to dig down) do not apply to it. A vault already in the new layout is returned as it is.
 */
export function normalize(v: VaultHome): VaultHome {
  // a vault that was only ever the first living room (and the entryway added beside it): nothing was built, so it starts again as the entryway alone
  const untouched = (rooms: { type: string; furniture: string[] }[]) => rooms.length > 0 && rooms.length <= 2 && rooms.every((r) => (r.type === 'living' || r.type === 'entry') && r.furniture.length === 0) && rooms.some((r) => r.type === 'living');
  if (v.settlers.length === 0 && untouched(v.rooms)) return { ...newVault(v.seenAt || Date.now(), v.seed ?? 0), from: v.from, sessionAt: v.sessionAt, seenAt: v.seenAt, boost: v.boost, boostAt: v.boostAt };
  let w: VaultHome = v;
  if (w.layout !== 2 && w.layout !== 3) {
    const rooms: VaultRoom[] = w.rooms.map((r) => ({ type: r.type, furniture: r.furniture, level: (r as unknown as { row: number }).row, col: r.col + 1, row: 1 }));
    const ahead: [number, number][] = [[0, 1], [4, 1], [1, 0], [1, 2], [2, 0], [2, 2], [3, 0], [3, 2]];
    const spot = ahead.find(([c, r]) => !rooms.some((x) => x.level === 0 && x.row === r && c >= x.col && c < x.col + roomDef(x.type).slots)) ?? [0, 1];
    rooms.unshift({ type: 'entry', level: 0, col: spot[0], row: spot[1], furniture: [] });
    w = { ...w, layout: 2, legacy: true, rooms };
  }
  // the dining chairs come with the table now, and the candle chandelier is gone
  if (w.rooms.some((r) => r.furniture.includes('chairs') || r.furniture.includes('chandelier'))) w = { ...w, rooms: w.rooms.map((r) => (r.furniture.includes('chairs') || r.furniture.includes('chandelier') ? { ...r, furniture: r.furniture.filter((x) => x !== 'chairs' && x !== 'chandelier'), ...(r.put ? { put: Object.fromEntries(Object.entries(r.put).filter(([k]) => k !== 'chairs' && k !== 'chandelier')) } : {}) } : r)) };
  // a stairwell made before they had an open end gets one: toward a room beside it
  if (w.rooms.some((r) => r.type === 'stairs' && !r.face)) w = { ...w, rooms: w.rooms.map((r) => (r.type === 'stairs' && !r.face ? { ...r, face: (Object.keys(FACE_STEP) as Face[]).find((f) => roomAt(w, r.level, r.col + FACE_STEP[f][0], r.row + FACE_STEP[f][1])) ?? 'l' } : r)) };
  // the first floorplan was five by three: it moves into the middle of the bigger one
  if (w.layout === 2) w = { ...w, layout: 3, rooms: w.rooms.map((r) => ({ ...r, col: r.col + 3, row: r.row + 3 })) };
  return w;
}

/** The price of the nth room slot: the second is 4 (the cheapest), the twentieth is 40 (the dearest), and it climbs gently at first and faster toward the end. */
export const slotPrice = (n: number): number => {
  if (n <= 2) return 4;
  if (n >= MAX_SLOTS) return MAX_ROOM_PRICE;
  return Math.round(4 + (MAX_ROOM_PRICE - 4) * Math.pow((n - 2) / (MAX_SLOTS - 2), 1.3));
};

/** Pieces of loot to build a room of this type now: the price of each slot it takes. A 2-slot room as your 4th slot costs 8 + 10. */
export function buildCost(v: VaultHome, type: RoomType): number {
  // a hallway is priced by how many hallways there are already, on the same climb as the rooms (the first costs what the cheapest room does)
  if (type === 'hallway') return slotPrice(v.rooms.filter((r) => r.type === 'hallway').length + 2);
  if (type === 'stairs') return slotPrice(stairwellsBuilt(v) + 2);
  const first = slotsUsed(v) + 1;
  return roomDef(type).slots === 2 ? Math.min(MAX_ROOM_PRICE, slotPrice(first) + slotPrice(first + 1)) : slotPrice(first);
}

/** Pieces of loot for the next piece of furniture in a room (3, 4, 5, then 6 for the last of four). */
export function furnishCost(r: VaultRoom): number {
  return 3 + r.furniture.length;
}

export const furnitureOf = (type: RoomType): FurnitureDef[] => roomDef(type).furniture;
/** The study's instrument is one slot with a choice: until chosen it is "instrument", then one of these. */
export const INSTRUMENTS = ['guitar', 'piano', 'harp', 'drums'] as const;
export const INSTRUMENT_NAMES: Record<string, string> = { guitar: 'Guitar', piano: 'Piano', harp: 'Harp', drums: 'Drum Set' };
/** Which slot of its room a placed piece fills (a guitar, a piano, a harp or a drum set fills the instrument slot). */
export const slotOf = (item: string): string => (item === 'instrument' || (INSTRUMENTS as readonly string[]).includes(item) ? 'instrument' : item);
export const roomComplete = (r: VaultRoom): boolean => r.furniture.length >= (r.type === 'hallway' ? 1 : furnitureOf(r.type).length);

// ---- what things cost, as a mix of loot ----

const KINDS = ['steel', 'wood', 'springs', 'adhesive', 'screws', 'concrete', 'glass', 'circuitry', 'oil', 'gears', 'plastic'];

/** A small repeatable random stream from a seed and a name (the same on the phone and on the server). */
function stream(seed: number, key: string): () => number {
  let h = (2166136261 ^ seed) >>> 0;
  for (let i = 0; i < key.length; i++) { h ^= key.charCodeAt(i); h = Math.imul(h, 16777619); }
  let a = h >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

/**
 * The mix of loot that adds up to this many pieces: two to five kinds, at least one of each, the rest dealt out at random ("2 wood, 1 plastic"; "1 steel,
 * 1 concrete, 1 screws"). The same seed and name always give the same mix. The cheap ones lean on steel and wood, which the very first raid pays.
 */
export function recipeFor(seed: number, key: string, pieces: number): LootBag {
  const next = stream(seed, key);
  const pool = KINDS.map((k) => ({ k, w: pieces <= 8 && (k === 'steel' || k === 'wood') ? 4 : 1 }));
  const most = Math.max(1, Math.min(pieces, 3 + Math.floor(pieces / 8), 5));
  const least = Math.min(pieces, 2);
  const kinds = least + Math.floor(next() * (most - least + 1));
  const chosen: string[] = [];
  for (let i = 0; i < kinds; i++) {
    let x = next() * pool.reduce((n, p) => n + p.w, 0);
    let at = 0;
    for (; at < pool.length - 1; at++) { x -= pool[at].w; if (x < 0) break; }
    chosen.push(pool[at].k);
    pool.splice(at, 1);
  }
  const bag: LootBag = {};
  chosen.forEach((k) => { bag[k] = 1; });
  for (let i = kinds; i < pieces; i++) { const k = chosen[Math.floor(next() * chosen.length)]; bag[k] = (bag[k] ?? 0) + 1; }
  return bag;
}

/** What building a room of this type costs now, as a mix of loot. */
export const buildRecipe = (v: VaultHome, type: RoomType): LootBag => recipeFor(v.seed ?? 0, `room:${type}:${type === 'hallway' ? v.rooms.filter((r) => r.type === 'hallway').length : type === 'stairs' ? stairwellsBuilt(v) : slotsUsed(v)}`, buildCost(v, type));
/** Pieces of loot a vacation vault costs, as a random mix (the same for the same place in the same vault, on the phone and on the server). */
export const VACATION_PIECES = 8;
export const vacationRecipe = (v: VaultHome, placeId: string): LootBag => recipeFor(v.seed ?? 0, `vacation:${placeId}`, VACATION_PIECES);
/** What the next piece of furniture in a room costs, as a mix of loot (each piece has its own). */
export const furnishRecipe = (v: VaultHome, roomIndex: number, item: string): LootBag => {
  const room = v.rooms[roomIndex];
  return room ? recipeFor(v.seed ?? 0, `item:${roomIndex}:${room.type}:${item}:${room.furniture.length}`, furnishCost(room)) : {};
};

// ---- settlers ----

/** The room slots that count toward settlers: everything but the entryway (and the passages). */
export const settlerSlots = (v: VaultHome): number => v.rooms.reduce((n, r) => n + (isPassage(r) || r.type === 'entry' ? 0 : slotsOf(r)), 0);
/** The first settler arrives with the third slot (not counting the entryway), and another with every four slots after it. */
export const settlersEarned = (v: VaultHome): number => { const n = settlerSlots(v); return n < 3 ? 0 : 1 + Math.floor((n - 3) / 4); };
export const settlersWaiting = (v: VaultHome): number => settlersEarned(v) - v.settlers.length;

// ---- happiness ----

export const DECAY_MS = 4 * 3_600_000;
export const VISIT_MS = 120_000;
/** A visit still counts as the same one if the screen was seen this recently. */
export const VISIT_GAP_MS = 60_000;
/** A temporary lift fades by one point per this long. */
export const BOOST_FADE_MS = 30 * 60_000;

/** Points from the rooms and furniture: they raise the floor and the baseline together. */
export const bonusPoints = (v: VaultHome): number => slotsUsed(v) + furnitureCount(v);
export const baselineOf = (v: VaultHome): number => 50 + bonusPoints(v);
export const floorOf = (v: VaultHome): number => 15 + bonusPoints(v);

export interface Mood { value: number; shown: number; baseline: number; floor: number; word: string; /** Which way it is going: up (climbing during a visit, or lifted by building a moment ago), down (settlers crowded in too few rooms), or neither. */ trend: 'up' | 'down' | null }

export const FACES: { min: number; word: string }[] = [
  { min: 90, word: 'ECSTATIC' },
  { min: 75, word: 'HAPPY' },
  { min: 60, word: 'CONTENT' },
  { min: 45, word: 'INDIFFERENT' },
  { min: 35, word: 'DISPLEASED' },
  { min: 25, word: 'SAD' },
  { min: -1, word: 'ANGRY' },
];

/** More settlers than the rooms provide for (rooms were demolished after they came): this many are crowded in. */
export const excessSettlers = (v: VaultHome): number => Math.max(0, v.settlers.length - settlersEarned(v));
/** With crowded settlers, happiness drops a point this often (instead of one every four hours) and a visit no longer lifts it. */
export const CROWDED_DECAY_MS = 10 * 60_000;
/** Crowded settlers leave after happiness has sat at its lowest this long; unhappy settlers with enough rooms steal one piece of loot this often. */
export const LEAVE_AFTER_MS = 24 * 3_600_000;
export const THEFT_EVERY_MS = 24 * 3_600_000;
/** At most this many pieces are taken in one go, however long the vault was left. */
export const MAX_THEFTS_AT_ONCE = 5;
/** The arrow points up for this long after something raised happiness. */
export const GAIN_SHOWN_MS = 5 * 60_000;

/** Where happiness is without the temporary lift: where it began, how it has moved, and when the slide down began. */
function drift(v: VaultHome, now: number) {
  const base = baselineOf(v);
  const floor = floorOf(v);
  const crowded = excessSettlers(v) > 0;
  const rate = crowded ? CROWDED_DECAY_MS : DECAY_MS;
  const seen = Math.min(now, v.seenAt);
  // crowded settlers are unhappy whether or not anyone is looking: the slide runs from the start of the visit; otherwise it runs from when the vault was last seen
  const end = crowded ? Math.min(now, v.sessionAt) : seen;
  const progress = Math.max(0, Math.min(1, (seen - v.sessionAt) / VISIT_MS));
  const start = !crowded && v.from < base ? v.from + (base - v.from) * progress : v.from;
  const value = Math.max(start - Math.floor(Math.max(0, now - end) / rate), floor);
  return { base, floor, crowded, rate, end, start, value, progress };
}

/** How happy the vault is at a moment: climbing toward the baseline during a visit, then slipping a point every four hours down to the floor (every ten minutes if settlers are crowded). */
export function moodAt(v: VaultHome, now: number): Mood {
  const d = drift(v, now);
  const lift = Math.max(0, v.boost - Math.floor(Math.max(0, now - v.boostAt) / BOOST_FADE_MS));
  const shown = Math.max(0, Math.min(100, Math.round(d.value + lift)));
  const f = FACES.find((x) => shown >= x.min) ?? FACES[FACES.length - 1];
  const climbing = !d.crowded && v.from < d.base && d.progress < 1;
  const gained = v.gainAt !== undefined && now - v.gainAt >= 0 && now - v.gainAt < GAIN_SHOWN_MS;
  const trend = climbing || gained ? 'up' : d.crowded && d.value > d.floor ? 'down' : null;
  return { value: d.value, shown, baseline: d.base, floor: d.floor, word: f.word, trend };
}

/** When happiness got to its lowest point and has stayed (ms), or null if it is above it. */
export function atFloorSince(v: VaultHome, now: number): number | null {
  const d = drift(v, now);
  if (d.value > d.floor) return null;
  if (v.floorAt !== undefined && d.start <= d.floor) return v.floorAt;
  return d.end + Math.max(0, d.start - d.floor) * d.rate;
}

/** Records that the vault is being looked at: a new visit starts if it has been a while, otherwise the current one goes on. */
export function checkIn(v: VaultHome, now: number): VaultHome {
  if (now - v.seenAt <= VISIT_GAP_MS) return { ...v, seenAt: now };
  const m = moodAt(v, now);
  return { ...v, from: m.value, sessionAt: now, seenAt: now, floorAt: atFloorSince(v, now) ?? undefined };
}

export interface Neglect { vault: VaultHome; /** Settlers who have left. */ left: Settler[]; /** How many pieces of loot have been taken. */ thefts: number }
/**
 * What has happened while happiness sat at its lowest. Crowded settlers (more than the rooms give) leave once it has been there a day, the latest to come first, as many as
 * are too many. Settlers who have enough rooms but are miserable stay and take one random piece of loot for every day of it; the server picks the piece.
 */
export function neglectAt(v: VaultHome, now: number): Neglect {
  const none: Neglect = { vault: v, left: [], thefts: 0 };
  const since = atFloorSince(v, now);
  if (since === null || v.settlers.length === 0) return none;
  const excess = excessSettlers(v);
  if (excess > 0) {
    if (now - since < LEAVE_AFTER_MS) return none;
    const keep = v.settlers.length - excess;
    return { vault: { ...v, settlers: v.settlers.slice(0, keep), stealFrom: now }, left: v.settlers.slice(keep), thefts: 0 };
  }
  const from = Math.max(since, v.stealFrom ?? 0);
  const days = Math.floor((now - from) / THEFT_EVERY_MS);
  if (days < 1) return none;
  const thefts = Math.min(days, MAX_THEFTS_AT_ONCE);
  return { vault: { ...v, stealFrom: days > thefts ? now : from + days * THEFT_EVERY_MS }, left: [], thefts };
}

/** However many things are built at once, the temporary lift never goes above this. */
export const MAX_BOOST = 30;

/** The temporary lift for spending this many pieces: 5 to 20 points. */
export const boostFor = (pieces: number): number => Math.max(5, Math.min(20, Math.round(4 + pieces * 0.55)));

/** Puts the current mood into the stored fields, so a change to the floor or baseline (a new room) starts from where the vault is now. */
function settle(v: VaultHome, now: number): VaultHome {
  const m = moodAt(v, now);
  const lift = Math.max(0, v.boost - Math.floor(Math.max(0, now - v.boostAt) / BOOST_FADE_MS));
  return { ...v, from: m.value, sessionAt: now, seenAt: now, boost: lift, boostAt: now, floorAt: atFloorSince(v, now) ?? undefined };
}

// ---- the things you can do (each returns the new vault, or the reason it cannot be done) ----

export type Action<T> = { ok: true; vault: VaultHome; cost: number; /** The exact mix of loot it costs. */ recipe: LootBag } & T | { ok: false; reason: string };

export function applyBuild(v: VaultHome, type: RoomType, level: number, col: number, row: number, now: number, dir: StairDir = 'down', shape: StairShape = 'straight'): Action<unknown> {
  if (!ROOM_DEFS.some((d) => d.id === type)) return { ok: false, reason: 'No such room' };
  if (dir !== 'up' && dir !== 'down') return { ok: false, reason: 'Up or down?' };
  if (shape !== 'straight' && shape !== 'u') return { ok: false, reason: 'Straight or U?' };
  const why = whyNotBuild(v, type, level, col, row, type === 'stairs' ? dir : undefined, type === 'stairs' ? shape : undefined);
  if (why) return { ok: false, reason: why };
  const cost = buildCost(v, type);
  const recipe = buildRecipe(v, type);
  const s = settle(v, now);
  // a stairwell has its twin on the level it goes to, where you arrive
  const u = type === 'stairs' && shape === 'u' ? uStairPlan(v, level, col, row, dir) : null;
  if (typeof u === 'string') return { ok: false, reason: u };
  if (u) {
    const twin: VaultRoom = { type, level: dir === 'down' ? level + 1 : level - 1, col: u.col, row: u.row, furniture: [], twin: true, face: u.face, shape: 'u', entry: u.entry === 0 ? 1 : 0 };
    return { ok: true, cost, recipe, vault: { ...s, rooms: [...s.rooms, { type, level, col: u.col, row: u.row, furniture: [], face: u.face, shape: 'u', entry: u.entry }, twin], boost: Math.min(MAX_BOOST, s.boost + boostFor(cost)), gainAt: now } };
  }
  const face = type === 'stairs' ? stairFace(v, level, col, row) : null;
  const made: VaultRoom[] = type === 'stairs' && face ? [{ type, level, col, row, furniture: [], face }, { type, level: dir === 'down' ? level + 1 : level - 1, col, row, furniture: [], twin: true, face: OPPOSITE[face] }] : [{ type, level, col, row, furniture: [] }];
  return { ok: true, cost, recipe, vault: { ...s, rooms: [...s.rooms, ...made], boost: Math.min(MAX_BOOST, s.boost + boostFor(cost)), gainAt: now } };
}

// ---- demolishing a room ----

/** The loot a room has cost in all, worked out the way each part was priced: building it (by how many slots there were before it), and every piece placed in it. */
export function spentOn(v: VaultHome, idx: number): LootBag {
  const room = v.rooms[idx];
  const total: LootBag = {};
  if (!room || room.type === 'entry') return total;
  const add = (bag: LootBag) => { for (const [k, n] of Object.entries(bag)) total[k] = (total[k] ?? 0) + (n ?? 0); };
  const before = v.rooms.slice(0, idx);
  const slotsBefore = before.reduce((n, r) => n + (isPassage(r) ? 0 : slotsOf(r)), 0);
  const hallsBefore = before.filter((r) => r.type === 'hallway').length;
  const stairsBefore = before.filter((r) => r.type === 'stairs' && !isTwin(r)).length;
  if (isTwin(room)) return total; // the twin of a built one: it cost nothing
  const first = slotsBefore + 1;
  const pieces = room.type === 'hallway' ? slotPrice(hallsBefore + 2) : room.type === 'stairs' ? slotPrice(stairsBefore + 2) : roomDef(room.type).slots === 2 ? Math.min(MAX_ROOM_PRICE, slotPrice(first) + slotPrice(first + 1)) : slotPrice(first);
  add(recipeFor(v.seed ?? 0, `room:${room.type}:${room.type === 'hallway' ? hallsBefore : room.type === 'stairs' ? stairsBefore : slotsBefore}`, pieces));
  room.furniture.forEach((item, k) => add(recipeFor(v.seed ?? 0, `item:${idx}:${room.type}:${slotOf(item)}:${k}`, 3 + k)));
  return total;
}

/** The twin made with a built stairwell (the stairwell in the same place on the next level, marked as a twin). */
const twinsOf = (v: VaultHome, room: VaultRoom): VaultRoom[] => (room.type === 'stairs' && !isTwin(room) ? v.rooms.filter((r) => isTwin(r) && r.col === room.col && r.row === room.row && Math.abs(r.level - room.level) === 1) : []);

/** Can this room be demolished? Null if yes, or the reason. */
export function whyNotDemolish(v: VaultHome, idx: number): string | null {
  const room = v.rooms[idx];
  if (!room) return 'No such room';
  if (room.type === 'entry') return 'The entryway cannot be demolished';
  // a stairwell is demolished from the end that was built, and takes its twin with it
  if (isTwin(room)) return 'This is the other end of a stairwell: demolish it from the end that was built';
  const gone = [room, ...twinsOf(v, room)];
  // everything left must still be joined to the entryway: next door on its level, or up and down a stairwell
  const left = v.rooms.filter((r) => !gone.includes(r));
  if (reachable(v, gone).size < left.length) return 'Other rooms are only reachable through it: demolish those first, or join them another way';
  return null;
}

/** Half of the loot (rounded down) a room cost comes back, each piece's kind picked at random from what was spent. */
export function refundFor(v: VaultHome, idx: number, rand: () => number = Math.random): LootBag {
  const spent = spentOn(v, idx);
  const pieces: string[] = [];
  for (const [k, n] of Object.entries(spent)) for (let i = 0; i < (n ?? 0); i++) pieces.push(k);
  for (let i = pieces.length - 1; i > 0; i--) { const j = Math.floor(rand() * (i + 1)); [pieces[i], pieces[j]] = [pieces[j], pieces[i]]; }
  const back: LootBag = {};
  for (const k of pieces.slice(0, Math.floor(pieces.length / 2))) back[k] = (back[k] ?? 0) + 1;
  return back;
}

/** Takes a room down: it goes back to being a place that could be built (with whatever was in it), and half of what it cost comes back. */
export function applyDemolish(v: VaultHome, idx: number, now: number, rand: () => number = Math.random): Action<{ refund: LootBag }> {
  const why = whyNotDemolish(v, idx);
  if (why) return { ok: false, reason: why };
  const refund = refundFor(v, idx, rand);
  const s = settle(v, now);
  // a built stairwell takes its twin on the level below with it
  const room = v.rooms[idx];
  const gone = [room, ...twinsOf(v, room)];
  return { ok: true, cost: 0, recipe: {}, refund, vault: { ...s, rooms: s.rooms.filter((r) => !gone.includes(r)) } };
}

/** Picks the instrument for a study's instrument slot (paid for already): it turns into the guitar, piano, harp or drum set chosen. */
export function applyInstrument(v: VaultHome, roomIndex: number, choice: string): Action<unknown> {
  const room = v.rooms[roomIndex];
  if (!room) return { ok: false, reason: 'No such room' };
  if (!(INSTRUMENTS as readonly string[]).includes(choice)) return { ok: false, reason: 'Not an instrument' };
  if (!room.furniture.includes('instrument')) return { ok: false, reason: 'There is no instrument waiting to be chosen' };
  return { ok: true, cost: 0, recipe: {}, vault: { ...v, rooms: v.rooms.map((r, i) => (i === roomIndex ? { ...r, furniture: r.furniture.map((x) => (x === 'instrument' ? choice : x)), ...(r.put?.instrument ? { put: Object.fromEntries(Object.entries(r.put).map(([k, p]) => [k === 'instrument' ? choice : k, p])) } : {}) } : r)) } };
}

export function applyFurnish(v: VaultHome, roomIndex: number, item: string, now: number, at?: unknown): Action<unknown> {
  const room = v.rooms[roomIndex];
  if (!room) return { ok: false, reason: 'No such room' };
  if (!furnitureOf(room.type).some((f) => f.id === item)) return { ok: false, reason: 'That does not belong in this room' };
  if (room.furniture.some((x) => slotOf(x) === slotOf(item))) return { ok: false, reason: 'Already there' };
  if (room.type === 'hallway' && room.furniture.length >= 1) return { ok: false, reason: 'A hallway holds one piece' };
  const cost = furnishCost(room);
  const recipe = furnishRecipe(v, roomIndex, item);
  const s = settle(v, now);
  const put = at === undefined ? null : cleanPut(at);
  if (at !== undefined && !put) return { ok: false, reason: 'That is not a place on the floor' };
  return { ok: true, cost, recipe, vault: { ...s, rooms: s.rooms.map((r, i) => (i === roomIndex ? { ...r, furniture: [...r.furniture, item], ...(put ? { put: { ...(r.put ?? {}), [item]: put } } : {}) } : r)), boost: Math.min(MAX_BOOST, s.boost + boostFor(cost)), gainAt: now } };
}

/** Moves a piece that is in a room already (free): it is put where the owner set it down. */
export function applyPlace(v: VaultHome, roomIndex: number, item: string, at: unknown): Action<unknown> {
  const room = v.rooms[roomIndex];
  if (!room) return { ok: false, reason: 'No such room' };
  if (!room.furniture.includes(item)) return { ok: false, reason: 'That piece is not in this room' };
  if (room.type === 'hallway') return { ok: false, reason: 'A hallway piece stays where it is' };
  const put = cleanPut(at);
  if (!put) return { ok: false, reason: 'That is not a place on the floor' };
  return { ok: true, cost: 0, recipe: {}, vault: { ...v, rooms: v.rooms.map((r, i) => (i === roomIndex ? { ...r, put: { ...(r.put ?? {}), [item]: put } } : r)) } };
}

export function applySettler(v: VaultHome, kind: string, name?: unknown): Action<unknown> {
  if (!SETTLER_KINDS.includes(kind as SettlerKind)) return { ok: false, reason: 'Not a settler' };
  if (settlersWaiting(v) < 1) return { ok: false, reason: 'No settler is waiting' };
  const clean = name === undefined ? undefined : cleanSettlerName(name);
  if (clean === null) return { ok: false, reason: 'A name is 1 to 10 letters or numbers' };
  const id = v.settlers.reduce((m, s) => Math.max(m, s.id), 0) + 1;
  return { ok: true, cost: 0, recipe: {}, vault: { ...v, settlers: [...v.settlers, { id, kind: kind as SettlerKind, ...(clean ? { name: clean } : {}) }] } };
}

/** Gives a settler a new name. */
export function applyRename(v: VaultHome, id: number, name: unknown): Action<unknown> {
  const clean = cleanSettlerName(name);
  if (!clean) return { ok: false, reason: 'A name is 1 to 10 letters or numbers' };
  if (!v.settlers.some((s) => s.id === id)) return { ok: false, reason: 'No such settler' };
  return { ok: true, cost: 0, recipe: {}, vault: { ...v, settlers: v.settlers.map((s) => (s.id === id ? { ...s, name: clean } : s)) } };
}
